import re
src = open('/challenge/CtfTask.v').read()
lines = src.split('\n')
start = None
for i,l in enumerate(lines):
    if l.startswith('module CtfTask'):
        start = i; break
end = None
for j in range(start, len(lines)):
    if lines[j].startswith('endmodule'):
        end = j; break

# Find FF instances (FDCE/FDPE) in top module
ffs = []
for i in range(start, end):
    l = lines[i]
    m = re.match(r'\s*(\$paramod\\FDCE\S*|\$paramod\\FDPE\S*)\s+(_\d+_)\s*\(', l)
    if m:
        # gather the port connections until ');'
        conns = {}
        j = i
        txt = l
        while ');' not in txt and j < end:
            j += 1
            txt += ' ' + lines[j]
        for pm in re.finditer(r'\.(\w+)\(([^)]*)\)', txt):
            conns[pm.group(1)] = pm.group(2).strip()
        ffs.append((m.group(1), m.group(2), conns))

print("num FF instances:", len(ffs))
for typ, name, conns in ffs:
    print(name, typ.split('\\')[-1], conns)

