    if name in lut_table_cache: return lut_table_cache[name]
    ports, inputs, outputs, assigns = parse_module(name)
    outname = outputs[0]
    n = len(inputs)
    # order inputs by I0..I(n-1): ensure the order of ports
    inport = [p for p in ports if p in ('I0','I1','I2','I3','I4','I5')]
    table=[0]*(1<<len(inport))
    for combo in range(1<<len(inport)):
        env = {inport[k]:(combo>>k)&1 for k in range(len(inport))}
        # evaluate assigns to fixpoint
        changed=True
        while changed:
            changed=False
            for lhs,rhs in assigns:
                val = ev(parse_expr(rhs), env)
                if env.get(lhs)!=val:
                    env[lhs]=val; changed=True
        table[combo]=env.get(outname,0)
    lut_table_cache[name]=table
    return table

