# gate kinds: LUT (has .O and .I0..), MUXCY, MUXF7/8, XORCY
# We'll evaluate with a fixpoint.

def build_comb(instances):
    # returns list of (outwire, module, inport_map) where inport_map: {I0:w1,...}
    gates = []
    for mod, inst, conn in instances:
        modn = mod.strip('\\')
        if modn == 'MUXCY':
            gates.append((conn.get('O'), 'muxcy', conn))
        elif modn in ('MUXF7','MUXF8'):
            gates.append((conn.get('O'), 'muxf', conn))
        elif modn == 'XORCY':
            gates.append((conn.get('O'), 'xorcy', conn))
        else:
