def parse_expr(s):
    toks=tokenize(s); pos=[0]
    def peek(): return toks[pos[0]] if pos[0]<len(toks) else None
    def nxt(): t=toks[pos[0]]; pos[0]+=1; return t
    def primary():
        t=nxt()
        if t=='(': e=ternary(); nxt(); return e
        if t=='~': return ('not',primary())
        if t=="1'h0": return ('const',0)
        if t=="1'h1": return ('const',1)
        return ('wire', t.lstrip('\\'))
