import re, sys

src = open('/challenge/CtfTask.v').read()
lines = src.split('\n')

# ---- parse modules ----
modules = {}   # name -> (ports, inputs, outputs, assigns)
i = 0
while i < len(lines):
    l = lines[i]
    if l.startswith('module '):
        name = l.split()[1]
        ports = [p.strip() for p in l.split('(',1)[1].rsplit(')',1)[0].split(',')]
        j = i+1; body=[]
        while not lines[j].startswith('endmodule'):
            body.append(lines[j]); j+=1
        inputs=[]; outputs=[]; assigns=[]
        for b in body:
            s=b.strip()
            if s.startswith('input '): inputs.append(s[6:].rstrip(';').strip())
            elif s.startswith('output '): outputs.append(s[7:].rstrip(';').strip())
            elif s.startswith('assign '):
                rhs=s[6:].rstrip(';').strip(); lhs,r=rhs.split('=',1)
                assigns.append((lhs.strip().lstrip('\\'), r.strip()))
        modules[name]=(ports, inputs, outputs, assigns)
        i=j+1
    else: i+=1

def tokenize(s):
    return re.findall(r"1'h[01]|\?|:|\||&|~|\^|\(|\)|[A-Za-z0-9_$\[\].]+", s)
def parse_expr(s):
    toks=tokenize(s); pos=[0]
    def peek(): return toks[pos[0]] if pos[0]<len(toks) else None
    def nxt(): t=toks[pos[0]]; pos[0]+=1; return t
    def primary():
        t=nxt()
        if t=='(': e=ternary(); nxt(); return e
        if t=='~': return ('not',primary())
        if t=="1'h0": return ('const',0)
        if t=="1'h1": return ('const',1)
        return ('wire', t.lstrip('\\'))
    def and_():
        e=primary()
        while peek()=='&': nxt(); e=('and',e,primary())
        return e
    def or_():
        e=and_()
        while peek()=='|': nxt(); e=('or',e,and_())
        return e
    def xor_():
        e=or_()
        while peek()=='^': nxt(); e=('xor',e,or_())
        return e
    def ternary():
        e=xor_()
        if peek()=='?': nxt(); a=ternary(); nxt(); b=ternary(); e=('mux',e,a,b)
        return e
    return ternary()
def ev(e,env):
    t=e[0]
    if t=='const': return e[1]
    if t=='wire': return env.get(e[1],0)
    if t=='not': return 1^ev(e[1],env)
    if t=='and': return ev(e[1],env)&ev(e[2],env)
    if t=='or': return ev(e[1],env)|ev(e[2],env)
    if t=='xor': return ev(e[1],env)^ev(e[2],env)
    if t=='mux': return ev(e[2],env) if ev(e[1],env) else ev(e[3],env)
    raise ValueError(e)
def init_from_name(name):
    m=re.search(r"INIT=([^\\]+)", name.replace('\\',''))
    if not m: return None
    s=m.group(1)
    if "'" in s:
        w,v=s.split("'"); return int(v.replace('_',''),2)
    return int(s)

tab_cache={}
def lut_table(name):
    if name in tab_cache: return tab_cache[name]
    ports,inputs,outputs,assigns=modules[name]
    outname=outputs[0]
    inport=[p for p in ports if p in ('I0','I1','I2','I3','I4','I5')]
    t=[0]*(1<<len(inport))
    exprs=[(lhs,parse_expr(rhs)) for lhs,rhs in assigns]
    for combo in range(1<<len(inport)):
        env={inport[k]:(combo>>k)&1 for k in range(len(inport))}
        changed=True
        while changed:
            changed=False
            for lhs,e2 in exprs:
                v=ev(e2,env)
                if env.get(lhs)!=v: env[lhs]=v; changed=True
        t[combo]=env.get(outname,0)
    tab_cache[name]=t
    return t

# ---- CtfTask instances ----
start=next(i for i,l in enumerate(lines) if l.startswith('module CtfTask'))
body=lines[start:]

instances=[]; ffs=[]
i=0
while i<len(body):
    l=body[i]
    m=re.match(r'\s*(\S+)\s+(\S+)\s*\(', l)
    if m and not l.strip().startswith(('module','endmodule','input','output','wire')):
        mod=m.group(1); txt=l; j=i+1
        while ');' not in txt: txt+=' '+body[j]; j+=1
        conn={}
        for pm in re.finditer(r'\.(\w+)\(\s*([^)]*?)\s*\)', txt):
            conn[pm.group(1)]=pm.group(2).strip().lstrip('\\')
        modn=mod.strip('\\')
        if 'FDCE' in modn or 'FDPE' in modn:
            kind='FDPE' if 'FDPE' in modn else 'FDCE'
            ffs.append((kind, conn.get('D'), conn.get('Q'), conn.get('CLR') or conn.get('PRE')))
        else:
            instances.append((mod, conn))
        i=j
    else: i+=1

def make_gates():
    g=[]
    for mod,conn in instances:
        modn=mod.strip('\\')
        o=conn.get('O')
        if modn=='MUXCY': g.append((o,'muxcy',conn))
        elif modn in ('MUXF7','MUXF8'): g.append((o,'muxf',conn))
        elif modn=='XORCY': g.append((o,'xorcy',conn))
        else: g.append((o,'lut',(mod,conn)))
    return g
gates=make_gates()

def eval_gate(g, env):
    o,kind,extra=g
    if kind=='muxcy':
        c=extra; return (env.get(c.get('CI'),0) if env.get(c.get('S'),0) else env.get(c.get('DI'),0))
    if kind=='muxf':
        c=extra; return env.get(c.get('I1'),0) if env.get(c.get('S'),0) else env.get(c.get('I0'),0)
    if kind=='xorcy':
        c=extra; return env.get(c.get('CI'),0)^env.get(c.get('LI'),0)
    mod,conn=extra
    inwires=[]
    for k in range(6):
        p=f'I{k}'
        if p in conn: inwires.append(conn[p])
        else: break
    idx=0
    for k,w in enumerate(inwires):
        idx |= (env.get(w,0)<<k)
    iv=init_from_name(mod)
    if iv is not None:
        return (iv>>idx)&1
    else:
        return lut_table(mod)[idx]

state = {Q:0 for kind,D,Q,CLR in ffs}

def tick(inp):
    env = dict(inp)
    for Q,v in state.items(): env[Q]=v
    for _ in range(len(gates)+1):
        ch=False
        for g in gates:
            o=g[0]
            if o is not None:
                v=eval_gate(g,env)
                if env.get(o)!=v: env[o]=v; ch=True
        if not ch: break
    reset=inp.get('reset',0)
    for kind,D,Q,CLR in ffs:
        d=env.get(D,0)
        state[Q]=(1 if reset else d) if kind=='FDPE' else (0 if reset else d)
    return env

def base_inp(reset=0, byte=None, done=0, temp=20):
    d={'reset':reset}
    for b in range(7): d[f'io_input[{b}]']=(byte>>b)&1 if byte is not None else 0
    d['io_inputDone']=done
    for b in range(8): d[f'io_temp[{b}]']=(temp>>b)&1
    return d

if __name__=='__main__':
    inp_str = "001003004099123321999000"
    sim_temp = 20.0
    # reset
    tick(base_inp(reset=1, temp=int(sim_temp)))
    tick(base_inp(reset=1, temp=int(sim_temp)))
    tick(base_inp(reset=0, temp=int(sim_temp)))
    print("power reg:", [state[Q] for kind,D,Q,CLR in ffs if '57bbd7' in Q])

    def send_byte(byte):
        tick(base_inp(temp=int(sim_temp), byte=byte, done=1))
        tick(base_inp(temp=int(sim_temp), byte=byte, done=0))

    def get_power():
        env={}
        for Q,v in state.items(): env[Q]=v
        env.update(base_inp(temp=int(sim_temp)))
        for _ in range(len(gates)+1):
            ch=False
            for g in gates:
                o=g[0]
                if o is not None:
                    v=eval_gate(g,env)
                    if env.get(o)!=v: env[o]=v; ch=True
            if not ch: break
        p=0
        for b in range(8): p |= (env.get(f'io_power[{b}]',0)<<b)
        return p

    for i in range(7):
        a,b_,c = inp_str[3*i], inp_str[3*i+1], inp_str[3*i+2]
        for ch in (a,b_,c, chr(10)):
            send_byte(ord(ch))
        power = get_power()
        sim_temp = min(255, max(0, sim_temp*(power/255.0+0.8)))
        tick(base_inp(temp=int(sim_temp)))
        print(f"[{i+1}] power={power}  temp={sim_temp:.0f}")

