    tick(base_inp(reset=1, temp=int(sim_temp)))
    tick(base_inp(reset=1, temp=int(sim_temp)))
    tick(base_inp(reset=0, temp=int(sim_temp)))
    print("power reg:", [state[Q] for kind,D,Q,CLR in ffs if '57bbd7' in Q])

    def send_byte(byte):
        tick(base_inp(temp=int(sim_temp), byte=byte, done=1))
        tick(base_inp(temp=int(sim_temp), byte=byte, done=0))

    def get_power():
        env={}
        for Q,v in state.items(): env[Q]=v
        env.update(base_inp(temp=int(sim_temp)))
        for _ in range(len(gates)+1):
            ch=False
            for g in gates:
                o=g[0]
                if o is not None:
                    v=eval_gate(g,env)
                    if env.get(o)!=v: env[o]=v; ch=True
            if not ch: break
        p=0
        for b in range(8): p |= (env.get(f'io_power[{b}]',0)<<b)
        return p

    for i in range(7):
        a,b_,c = inp_str[3*i], inp_str[3*i+1], inp_str[3*i+2]
        for ch in (a,b_,c, chr(10)):
            send_byte(ord(ch))
        power = get_power()
        sim_temp = min(255, max(0, sim_temp*(power/255.0+0.8)))
        tick(base_inp(temp=int(sim_temp)))
        print(f"[{i+1}] power={power}  temp={sim_temp:.0f}")

