import re, sys, itertools

src = open('/challenge/CtfTask.v').read()

def parse_expr(s, env):
    s = s.strip()
    s = re.sub(r"1'h0", '0', s)
    s = re.sub(r"1'h1", '1', s)
    s = re.sub(r"1'b0", '0', s)
    s = re.sub(r"1'b1", '1', s)
    if '?' in s:
        q = s.find('?')
        cond = s[:q]
        rest = s[q+1:]
        depth = 0; colon = -1
        for i,c in enumerate(rest):
            if c=='?': depth+=1
            elif c==':':
                if depth==0: colon=i; break
                else: depth-=1
        tb = rest[:colon]; fb = rest[colon+1:]
        return parse_expr(tb, env) if parse_expr(cond, env) else parse_expr(fb, env)
    # handle ~ (unary not) — find first ~ 
    if '~' in s:
        i = s.find('~')
        return 1 - parse_expr(s[i+1:].strip(), env)
    if '&' in s:
        a,b = s.split('&',1)
        return parse_expr(a,env) & parse_expr(b,env)
    if '|' in s:
        a,b = s.split('|',1)
        return parse_expr(a,env) | parse_expr(b,env)
    if '^' in s:
        a,b = s.split('^',1)
        return parse_expr(a,env) ^ parse_expr(b,env)
    s=s.strip()
    if s=='0': return 0
    if s=='1': return 1
    return env[s]

module_re = re.compile(r'module\s+([^\s(]+)\s*\(([^)]*)\)\s*;(.*?)endmodule', re.S)
modules = {}
for m in module_re.finditer(src):
    name = m.group(1)
    ports = [p.strip() for p in m.group(2).split(',') if p.strip()]
    body = m.group(3)
    modules[name] = (ports, body)

def build_lut_truth(ports, body):
    inputs = [p for p in ports if p != 'O']
    n = len(inputs)
    assigns = []
    for line in body.split('\n'):
        m2 = re.match(r'\s*assign\s+([^\s=]+)\s*=\s*(.*?);', line)
        if m2:
            assigns.append((m2.group(1), m2.group(2)))
    table = []
    for combo in itertools.product([0,1], repeat=n):
        env = dict(zip(inputs, combo))
        vals = {}
        for _ in range(40):
            for lhs, rhs in assigns:
                try:
                    vals[lhs] = parse_expr(rhs, {**env, **vals})
                except KeyError:
                    pass
        table.append(vals.get('O', 0))
    return inputs, table

lut_tables = {}
prim_module_names = set()
for name,(ports,body) in modules.items():
    if 'LUT' in name and 'MUX' not in name and 'CY' not in name:
        inputs, table = build_lut_truth(ports, body)
        lut_tables[name] = table

# parse main module
cports, cbody = modules['CtfTask']

instances = []
for m in re.finditer(r'^\s*(\S+)\s+(_\d+_)\s*\(', cbody, re.M):
    close = cbody.find(');', m.end())
    porttext = cbody[m.end():close]
    mtype = m.group(1); iname = m.group(2)
    pm = {}
    for mm in re.finditer(r'\.([A-Za-z0-9_]+)\s*\(\s*([^)]*?)\s*\)', porttext):
        pm[mm.group(1)] = mm.group(2).strip()
    instances.append((mtype, iname, pm))

def norm(s):
    s = s.strip()
    # strip leading backslashes
    while s.startswith('\\'):
        s = s[1:]
    return s

ffs = {}   # Q_signal -> (D_signal, is_pre_reset)
combs = []
for mtype, iname, pm in instances:
    if 'FDCE' in mtype:
        q = norm(pm['Q']); d = norm(pm['D'])
        ffs[q] = (d, False)
    elif 'FDPE' in mtype:
        q = norm(pm['Q']); d = norm(pm['D'])
        ffs[q] = (d, True)
    else:
        combs.append((mtype, pm))

# FF Q order & reset values: FDCE clear to 0 on reset, FDPE preset to 1 on reset.
# Build list of FF Q signals.
ffq = list(ffs.keys())

# For combinational evaluation, we need to compute, given:
#   FF Q values (dict sig->value)
#   io_input[0..6], io_temp[0..7], io_inputDone, reset
# the outputs: io_power[0..7], and each FF's D signal value.
# We do fixpoint: maintain sig -> value. Start with known inputs + FF Q.

def eval_comb(ffq_vals, io_input, io_temp, io_inputDone, reset):
    S = {}
    for i in range(7): S['io_input[%d]'%i] = (io_input>>i)&1
    for i in range(8): S['io_temp[%d]'%i] = (io_temp>>i)&1
    S['io_inputDone'] = io_inputDone
    S['reset'] = reset
    S['clk'] = 0
    for q,v in ffq_vals.items():
        S[q] = v
    # iterate comb instances until fixpoint
    for it in range(200):
        changed = False
        for mtype, pm in combs:
            if mtype in lut_tables:
                tbl = lut_tables[mtype]
                # inputs I0..I(n-1)
                keys = ['I0','I1','I2','I3','I4','I5','I6','I7']
                idx = 0
                vals = {}
                for k in keys:
                    if k in pm:
                        sig = norm(pm[k])
                        v = S.get(sig)
                        if v is None:
                            v = None; break
                        vals[k]=v
                else:
                    # compute idx
                    idx = 0
                    for j,k in enumerate(keys):
                        if k in pm:
                            idx |= (vals[k] << j)
                    o = tbl[idx]
                    osig = norm(pm['O'])
                    if S.get(osig) != o:
                        S[osig]=o; changed=True
            elif mtype=='MUXF7' or mtype=='MUXF8':
                # O = S ? I1 : I0
                s = S.get(norm(pm['S']))
                i0 = S.get(norm(pm['I0'])); i1 = S.get(norm(pm['I1']))
                if s is None or i0 is None or i1 is None: continue
                o = i1 if s else i0
                osig = norm(pm['O'])
                if S.get(osig)!=o: S[osig]=o; changed=True
            elif mtype=='MUXCY':
                # O = S ? CI : DI
                s=S.get(norm(pm['S'])); ci=S.get(norm(pm['CI'])); di=S.get(norm(pm['DI']))
                if s is None or ci is None or di is None: continue
                o = ci if s else di
                osig=norm(pm['O'])
                if S.get(osig)!=o: S[osig]=o; changed=True
            elif mtype=='XORCY':
                ci=S.get(norm(pm['CI'])); li=S.get(norm(pm['LI']))
                if ci is None or li is None: continue
                o = ci ^ li
                osig=norm(pm['O'])
                if S.get(osig)!=o: S[osig]=o; changed=True
            else:
                # LUT2/3/4/5 with INIT in name — but we captured those in lut_tables? 
                # names like \paramod\LUT2\INIT... contain 'LUT'. They are in lut_tables keyed by full name.
                pass
        if not changed:
            break
    # compute io_power
    power = 0
    for i in range(8):
        power |= (S.get('io_power[%d]'%i, 0) << i)
    # compute next D values for FFs
    next_ff = {}
    for q,(d,pre) in ffs.items():
        next_ff[q] = S.get(d, 0)
    return power, next_ff, S

# clock: Q <= D (with reset override)
def clock(ffq_vals, next_ff, reset):
    out = {}
    for q in ffq:
        pre = ffs[q][1]
        if reset:
            out[q] = 1 if pre else 0
        else:
            out[q] = next_ff[q]
    return out

# reset: clear all FFs (FDCE->0, FDPE->1)
def do_reset():
    ffq_vals = {}
    for q,(d,pre) in ffs.items():
        ffq_vals[q] = 1 if pre else 0
    # run a couple comb/clock cycles with reset=1
    for _ in range(3):
        power, next_ff, S = eval_comb(ffq_vals, 0, 0, 0, 1)
        ffq_vals = clock(ffq_vals, next_ff, 1)
    return ffq_vals

ffq_vals = do_reset()
# print initial state
for q in sorted(ffq_vals, key=lambda x: ffq_vals[x]):
    if ffq_vals[q]: print("INIT", q, "=", ffq_vals[q])

print("FF list:", sorted(ffq_vals.keys()))

