def eval_comb(ffq_vals, io_input, io_temp, io_inputDone, reset):
    S = {}
    for i in range(7): S['io_input[%d]'%i] = (io_input>>i)&1
    for i in range(8): S['io_temp[%d]'%i] = (io_temp>>i)&1
    S['io_inputDone'] = io_inputDone
