                vals = {}
                for k in keys:
                    if k in pm:
                        sig = norm(pm[k])
                        v = S.get(sig)
                        if v is None:
                            v = None; break
                        vals[k]=v
                else:
                    # compute idx
                    idx = 0
                    for j,k in enumerate(keys):
                        if k in pm:
                            idx |= (vals[k] << j)
                    o = tbl[idx]
