                if s is None or i0 is None or i1 is None: continue
                o = i1 if s else i0
                osig = norm(pm['O'])
                if S.get(osig)!=o: S[osig]=o; changed=True
            elif mtype=='MUXCY':
                # O = S ? CI : DI
                s=S.get(norm(pm['S'])); ci=S.get(norm(pm['CI'])); di=S.get(norm(pm['DI']))
                if s is None or ci is None or di is None: continue
                o = ci if s else di
                osig=norm(pm['O'])
                if S.get(osig)!=o: S[osig]=o; changed=True
            elif mtype=='XORCY':
                ci=S.get(norm(pm['CI'])); li=S.get(norm(pm['LI']))
                if ci is None or li is None: continue
                o = ci ^ li
                osig=norm(pm['O'])
                if S.get(osig)!=o: S[osig]=o; changed=True
            else:
                # LUT2/3/4/5 with INIT in name — but we captured those in lut_tables? 
                # names like \paramod\LUT2\INIT... contain 'LUT'. They are in lut_tables keyed by full name.
                pass
        if not changed:
            break
    # compute io_power
    power = 0
    for i in range(8):
        power |= (S.get('io_power[%d]'%i, 0) << i)
    # compute next D values for FFs
    next_ff = {}
    for q,(d,pre) in ffs.items():
        next_ff[q] = S.get(d, 0)
    return power, next_ff, S

# clock: Q <= D (with reset override)
def clock(ffq_vals, next_ff, reset):
    out = {}
    for q in ffq:
        pre = ffs[q][1]
        if reset:
            out[q] = 1 if pre else 0
        else:
            out[q] = next_ff[q]
    return out

# reset: clear all FFs (FDCE->0, FDPE->1)
def do_reset():
    ffq_vals = {}
    for q,(d,pre) in ffs.items():
        ffq_vals[q] = 1 if pre else 0
    # run a couple comb/clock cycles with reset=1
    for _ in range(3):
        power, next_ff, S = eval_comb(ffq_vals, 0, 0, 0, 1)
        ffq_vals = clock(ffq_vals, next_ff, 1)
    return ffq_vals

