import re, sys, itertools, collections

src = open('/challenge/CtfTask.v').read()

def norm(s):
    return s.replace('\\','').strip()

# ---- expression parser (recursive descent, handles ?:  ~ & | ^) ----
def parse_expr(s, env):
    s = s.strip()
    s = s.replace("1'h0",'0').replace("1'h1",'1').replace("1'b0",'0').replace("1'b1",'1')
    s = s.replace('\\','')
    # find top-level ? :
    if '?' in s:
        depth = 0
        # find the matching ':' for the first '?'
        q = s.find('?')
        cond = s[:q]
        rest = s[q+1:]
        depth = 0
        colon = -1
        for i,c in enumerate(rest):
            if c=='?': depth+=1
            elif c==':':
                if depth==0:
                    colon=i; break
                else: depth-=1
        if colon>=0:
            tb = rest[:colon]; fb = rest[colon+1:]
            return parse_expr(tb, env) if parse_expr(cond, env) else parse_expr(fb, env)
    # ~ (unary)
    # careful: find leading ~ or ~ at start after nothing. Only treat first char if '~'
    if s.startswith('~'):
        return 1 - parse_expr(s[1:].strip(), env)
    # & | ^ handled with lowest precedence -> actually these are simple; but do rightmost split? 
    # In netlist, only & and | appear, no mixing.  Process '|' lowest, '&' higher, '^' higher.
    # find top-level | (outside any parens; there are none)
    depth=0
    for i in range(len(s)-1,-1,-1):
        c=s[i]
        if c==')': depth+=1
        elif c=='(': depth-=1
        elif c=='|' and depth==0:
            return parse_expr(s[:i],env) | parse_expr(s[i+1:],env)
    for i in range(len(s)-1,-1,-1):
        c=s[i]
        if c=='&' and s[:i].count('(')==s[:i].count(')'):
            return parse_expr(s[:i],env) & parse_expr(s[i+1:],env)
    for i in range(len(s)-1,-1,-1):
        c=s[i]
        if c=='^':
            return parse_expr(s[:i],env) ^ parse_expr(s[i+1:],env)
    s=s.strip()
    if s=='0': return 0
    if s=='1': return 1
    return env[s]

# ---- parse modules ----
module_re = re.compile(r'module\s+([^\s(]+)\s*\(([^)]*)\)\s*;(.*?)endmodule', re.S)
modules = {}
for m in module_re.finditer(src):
    name = m.group(1).replace('\\','')
    ports = [p.replace('\\','').strip() for p in m.group(2).split(',') if p.strip()]
    body = m.group(3)
    modules[name] = (ports, body)

# For each LUT / LUT2/3/4/6 module: extract assigns as (lhs, rhs)
def get_assigns(body):
    out=[]
    for line in body.split('\n'):
        m2 = re.match(r'\s*assign\s+([^=]+?)\s*=\s*(.*?)\s*;\s*$', line)
        if m2:
            out.append((norm(m2.group(1)), m2.group(2)))
    return out

# ---- parse CtfTask instances ----
i = src.index('module CtfTask(')
cbody = src[i:]

# instances: type, name, portmap
instances=[]
for m in re.finditer(r'^\s*(\S+)\s+(_\d+_)\s*\((.*?)\);', cbody, re.S|re.M):
    mtype = norm(m.group(1)); name=m.group(2); ptxt=m.group(3)
    pm={}
    for mm in re.finditer(r'\.([A-Za-z0-9_]+)\s*\(\s*([^)]*?)\s*\)', ptxt):
        pm[mm.group(1)] = norm(mm.group(2))
    instances.append((mtype,name,pm))

# classify
ffs = {}   # Q -> (D, is_preset)
combs = []  # (mtype, pm)
for mtype, name, pm in instances:
    if 'FDCE' in mtype:
        q = pm.get('Q'); d = pm.get('D')
        if q: ffs[q]=(d, False)
    elif 'FDPE' in mtype:
        q=pm.get('Q'); d=pm.get('D')
        if q: ffs[q]=(d, True)
    elif 'FDRE' in mtype:
        q=pm.get('Q'); d=pm.get('D')
        if q: ffs[q]=(d, False)
    else:
        combs.append((mtype, pm))

ffq = list(ffs.keys())
print("FF count:", len(ffq), "comb cells:", len(combs))

# precompute assign lists for LUT modules
lut_assigns = {}
for name,(ports,body) in modules.items():
    if 'LUT' in name:  # LUTn
        lut_assigns[name]=get_assigns(body)

def eval_lut(mtype, pm, S):
    ass = lut_assigns.get(mtype)
    if ass is None:
        return None
    env={}
    # map I0..I(n) to their signal values from S
    for k in ['I0','I1','I2','I3','I4','I5','I6','I7']:
        if k in pm:
            v = S.get(pm[k])
            if v is None: return None
            env[k]=v
    vals={}
    for _ in range(60):
        changed=False
        for lhs,rhs in ass:
            try:
                v = parse_expr(rhs, {**env, **vals})
            except KeyError:
                continue
            if vals.get(lhs)!=v:
                vals[lhs]=v; changed=True
        if not changed: break
    return vals.get('O',0)

def eval_comb(ffq_vals, io_input, io_temp, io_inputDone, reset):
    S={}
