import re, sys, itertools, collections

src = open('/challenge/CtfTask.v').read()

def norm(s):
    return s.replace('\\','').strip()

# ---- expression parser (recursive descent, handles ?:  ~ & | ^) ----
def parse_expr(s, env):
    s = s.strip()
    s = s.replace("1'h0",'0').replace("1'h1",'1').replace("1'b0",'0').replace("1'b1",'1')
    s = s.replace('\\','')
    # find top-level ? :
    if '?' in s:
        depth = 0
        # find the matching ':' for the first '?'
        q = s.find('?')
        cond = s[:q]
        rest = s[q+1:]
        depth = 0
        colon = -1
        for i,c in enumerate(rest):
            if c=='?': depth+=1
            elif c==':':
                if depth==0:
                    colon=i; break
                else: depth-=1
        if colon>=0:
            tb = rest[:colon]; fb = rest[colon+1:]
            return parse_expr(tb, env) if parse_expr(cond, env) else parse_expr(fb, env)
    # ~ (unary)
    # careful: find leading ~ or ~ at start after nothing. Only treat first char if '~'
    if s.startswith('~'):
        return 1 - parse_expr(s[1:].strip(), env)
    # & | ^ handled with lowest precedence -> actually these are simple; but do rightmost split? 
    # In netlist, only & and | appear, no mixing.  Process '|' lowest, '&' higher, '^' higher.
    # find top-level | (outside any parens; there are none)
    depth=0
    for i in range(len(s)-1,-1,-1):
        c=s[i]
        if c==')': depth+=1
        elif c=='(': depth-=1
        elif c=='|' and depth==0:
            return parse_expr(s[:i],env) | parse_expr(s[i+1:],env)
    for i in range(len(s)-1,-1,-1):
        c=s[i]
        if c=='&' and s[:i].count('(')==s[:i].count(')'):
            return parse_expr(s[:i],env) & parse_expr(s[i+1:],env)
    for i in range(len(s)-1,-1,-1):
        c=s[i]
        if c=='^':
            return parse_expr(s[:i],env) ^ parse_expr(s[i+1:],env)
    s=s.strip()
    if s=='0': return 0
    if s=='1': return 1
    return env[s]

